// Differential tests for uos/rt/text_codec.hpp. Every expected value between the
// generated-vectors markers was produced by Bun 1.4.0 (the oracle): TextEncoder,
// Buffer.from(string), TextDecoder one-shot/fatal/ignoreBOM/streaming, Buffer
// toString("utf8") and the label table. The cases after the markers pin the WTF-8
// storage convention (docs/rt/text.md) and the documented label bound.
#include "uos/rt/string.hpp"
#include "uos/rt/limits.hpp"
#include "uos/rt/test.hpp"
#include "uos/rt/text_codec.hpp"

#include <cstdint>
#include <span>
#include <string>
#include <string_view>
#include <vector>

using namespace std::string_view_literals;
namespace rt = uos::rt;

namespace {
  std::span<const std::uint8_t> bytesOf(std::string_view text) { return {reinterpret_cast<const std::uint8_t*>(text.data()), text.size()}; }
  std::vector<std::uint8_t> vectorOf(std::string_view text) { return {bytesOf(text).begin(), bytesOf(text).end()}; }

  template <class A, class B>
  void rowEqual(const A& actual, const B& expected, const char* text, std::size_t row, int line) {
    if (!(actual == expected)) {
      ::uos::rt::test::report(__FILE__, line, "row " + std::to_string(row) + ": " + text + "\n      actual:   " + ::uos::rt::test::show(actual) + "\n      expected: " + ::uos::rt::test::show(expected), false);
    }
  }
  void rowTrue(bool condition, const char* text, std::size_t row, int line) {
    if (!condition) ::uos::rt::test::report(__FILE__, line, "row " + std::to_string(row) + ": expected " + text, false);
  }

  // "Name: message" of the rt::JsError the call throws, or "(no error)".
  template <class F>
  std::string thrownText(F&& call) {
    try {
      (void)call();
    } catch (const rt::JsError& error) {
      return error.toString();
    }
    return "(no error)";
  }
}

#define ROW_EQ(row, actual, expected) rowEqual((actual), (expected), #actual, (row), __LINE__)
#define ROW_TRUE(row, condition) rowTrue((condition), #condition, (row), __LINE__)

